 'use strict';
const LOOT_RARITIES={common:{name:'Common',color:'#ffffff',chance:50,min:0,max:0},rare:{name:'Rare',color:'#80c5ff',chance:35,min:1,max:1},epic:{name:'Epic',color:'#cc91ff',chance:10,min:2,max:2},legend:{name:'Legend',color:'#ffe06a',chance:5,min:3,max:4}};
const BOX_TYPES={main:'กล่องอาวุธหลัก',secondary:'กล่องสุ่มสกิล',armor:'กล่องอุปกรณ์สวมใส่',accessory:'กล่องประดับ'};
const GEAR_SLOTS=['main','secondary','hat','shirt','gloves','shoes','accessory1','accessory2'];
const BONUS_NAMES={str:'STR',dex:'DEX',int:'INT',luk:'LUK',hp:'HP',mp:'MP',atk:'ATK',atkspd:'ATKSPD',def:'DEF',cri:'CRI',criDamage:'CRI.DAMAGE',acc:'ACC',ignoreDef:'IGNORE.DEF',damage:'DAMAGE',bossDamage:'BOSS.DAMAGE'};
function boxTierForLevel(level){return level>=100?100:level>=60?60:level>=30?30:level>=10?10:0}
function rarityRoll(value=Math.random()){return value<.5?'common':value<.85?'rare':value<.95?'epic':'legend'}
function validateLoot(raw,legacyLevel=10){const out={money:0,boxes:{main:0,secondary:0,armor:0,accessory:0},boxLevels:{main:{},secondary:{},armor:{},accessory:{}},gear:[],equipped:{}};if(raw===undefined)return out;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ข้อมูลไอเทมไม่ถูกต้อง');const integer=(v,max)=>Number.isInteger(v)&&v>=0&&v<=max;if(!integer(raw.money,999999999))throw Error('จำนวนเงินไม่ถูกต้อง');out.money=raw.money;for(const k of Object.keys(BOX_TYPES)){if(!integer(raw.boxes?.[k],999999))throw Error('จำนวนกล่องไม่ถูกต้อง');out.boxes[k]=raw.boxes[k]}for(const type of Object.keys(BOX_TYPES)){const levels=raw.boxLevels?.[type];if(raw.boxLevels===undefined){if(out.boxes[type])out.boxLevels[type][boxTierForLevel(legacyLevel)||10]=out.boxes[type]}else{if(!levels||typeof levels!=='object'||Array.isArray(levels))throw Error('เลเวลกล่องไม่ถูกต้อง');let total=0;for(const [level,count]of Object.entries(levels)){if(!/^[1-9][0-9]*$/.test(level)||Number(level)>999||!integer(count,999999)||count===0)throw Error('กองกล่องไม่ถูกต้อง');const tier=boxTierForLevel(Number(level))||10;out.boxLevels[type][tier]=(out.boxLevels[type][tier]||0)+count;total+=count}if(total!==out.boxes[type])throw Error('จำนวนกล่องไม่ตรงกอง')}}if(!Array.isArray(raw.gear)||raw.gear.length>10000)throw Error('กระเป๋าอุปกรณ์ไม่ถูกต้อง');const ids=new Set();for(const g of raw.gear){if(!g||typeof g.id!=='string'||g.id.length>80||ids.has(g.id)||!GEAR_SLOTS.includes(g.slot)||!LOOT_RARITIES[g.rarity]||typeof g.name!=='string'||g.name.length>80||!integer(g.stage,4))throw Error('อุปกรณ์ไม่ถูกต้อง');if(g.weapon!==undefined&&g.weapon!==null&&!WEAPON_NAMES[g.weapon]&&g.weapon!=='axe')throw Error('ประเภทอาวุธไม่ถูกต้อง');const tier=LOOT_RARITIES[g.rarity];if(!Array.isArray(g.bonuses)||g.bonuses.length<tier.min||g.bonuses.length>tier.max)throw Error('พลังพิเศษอุปกรณ์ไม่ถูกต้อง');const unique=new Set();for(const b of g.bonuses){if(!BONUS_NAMES[b.key]||unique.has(b.key)||!integer(b.value,1000)||b.value===0)throw Error('พลังพิเศษอุปกรณ์ไม่ถูกต้อง');unique.add(b.key)}for(const key of ['atk','def','hp','mp'])if(!integer(g[key]??0,10000))throw Error('ค่าพลังอุปกรณ์ไม่ถูกต้อง');ids.add(g.id);if(g.level!==undefined&&(!integer(g.level,999)||g.level<1))throw Error('เลเวลอุปกรณ์ไม่ถูกต้อง');out.gear.push({...structuredClone(g),level:g.level??(g.stage===0?1:g.stage===4?30:g.stage*10)})}for(const slot of GEAR_SLOTS){const id=raw.equipped?.[slot];if(id!==undefined&&id!==null){if(!out.gear.some(g=>g.id===id&&g.slot===slot))throw Error('ช่องสวมใส่ไม่ถูกต้อง');out.equipped[slot]=id}}return out}
function gearDescription(g){const base=['atk','def','hp','mp'].filter(k=>g[k]).map(k=>k.toUpperCase()+' +'+g[k]);const bonuses=g.bonuses.map(b=>BONUS_NAMES[b.key]+' +'+b.value+(['cri','criDamage','ignoreDef','damage','bossDamage'].includes(b.key)?'%':''));return LOOT_RARITIES[g.rarity].name+' · '+g.name+' · Lv.'+(g.level??(g.stage?g.stage*10:1))+'\n'+base.join(' · ')+'\n'+(bonuses.length?'สเตตัสพิเศษ\n'+bonuses.join('\n'):'ไม่มีสเตตัสพิเศษ')}
function generateGear(type,stage=0,level=stage===0?1:stage===4?30:stage*10){const slot=type==='armor'?['hat','shirt','gloves','shoes'][Math.floor(Math.random()*4)]:type==='accessory'?['accessory1','accessory2'][Math.floor(Math.random()*2)]:type;const names={main:'ดาบนักเดินทาง',secondary:'โล่นักเดินทาง',hat:'หมวกนักเดินทาง',shirt:'เสื้อนักเดินทาง',gloves:'ถุงมือนักเดินทาง',shoes:'รองเท้านักเดินทาง',accessory1:'แหวนป่า',accessory2:'สร้อยป่า'};const scale=Math.max(0,Math.floor(level/10));const weapon=type==='main'?validClass().weapons[Math.floor(Math.random()*validClass().weapons.length)]:null;const rarity=rarityRoll(),tier=LOOT_RARITIES[rarity],count=tier.min+Math.floor(Math.random()*(tier.max-tier.min+1)),pool=Object.keys(BONUS_NAMES);const bonuses=[];for(let i=0;i<count;i++){const key=pool.splice(Math.floor(Math.random()*pool.length),1)[0];bonuses.push({key,value:['hp','mp'].includes(key)?10+scale*5:1+Math.floor(Math.random()*3)+scale})}return {id:crypto.randomUUID(),name:weapon?WEAPON_NAMES[weapon]+'นักเดินทาง':names[slot],weapon,slot,rarity,stage,level,atk:slot==='main'?17+scale*4:0,def:slot==='main'?0:3+scale,hp:slot.startsWith('accessory')?20+scale*10:0,mp:0,bonuses}}
function randomBoxType(){const types=Object.keys(BOX_TYPES);return types[Math.floor(Math.random()*types.length)]}
function boxType(id){return String(id).split('@')[0]}
function boxLevel(id){const explicit=Number(String(id).split('@')[1]);return explicit||Number(Object.keys(player.loot.boxLevels?.[id]||{}).sort((a,b)=>a-b)[0])||10}
function boxKey(type,level){return type+'@'+level}
function boxCount(id){return player.loot.boxLevels?.[boxType(id)]?.[boxLevel(id)]||0}
function skillBoxTier(id){const lv=boxLevel(id);return lv>=100?4:lv>=60?3:lv>=30?2:1}
function boxName(id){if(boxType(id)==='secondary')return 'กล่องสุ่มสกิล ขั้น '+skillBoxTier(id);return BOX_TYPES[boxType(id)]+' · Lv.'+boxLevel(id)}
function boxDescription(id){if(boxType(id)==='secondary')return 'สุ่มสกิลขั้น '+skillBoxTier(id)+' · Active/Buff/Passive · ใช้สกิลซ้ำอัปถึง Lv.30';return 'สุ่มได้อุปกรณ์เลเวล '+boxLevel(id)+' · Common 50% / Rare 35% / Epic 10% / Legend 5%'}
function boxStacks(){return Object.keys(BOX_TYPES).flatMap(type=>Object.entries(player.loot.boxLevels?.[type]||{}).sort(([a],[b])=>a-b).filter(([,count])=>count>0).map(([level,count])=>({type:boxKey(type,level),id:boxKey(type,level),name:boxName(boxKey(type,level)),count})))}
function addBox(type,level=10){if(!BOX_TYPES[type]||![10,30,60,100].includes(level)||player.loot.boxes[type]>=999999)return false;player.loot.boxLevels??=Object.fromEntries(Object.keys(BOX_TYPES).map(t=>[t,{}]));player.loot.boxLevels[type]??={};player.loot.boxLevels[type][level]=(player.loot.boxLevels[type][level]||0)+1;player.loot.boxes[type]++;return true}
function consumeBoxes(id,quantity){const type=boxType(id),level=boxLevel(id);if(!Number.isInteger(quantity)||quantity<1||boxCount(id)<quantity)return false;player.loot.boxLevels[type][level]-=quantity;if(!player.loot.boxLevels[type][level])delete player.loot.boxLevels[type][level];player.loot.boxes[type]-=quantity;return true}
function rollMonsterLoot(m){if(run?.trial||m.boss||(!m.elite&&Math.random()>=.01))return null;const type=randomBoxType();const level=boxTierForLevel(stageById(run.id)?.level||m.level||0);if(!level)return null;if(!addBox(type,level))return null;(run.droppedBoxes??=[]).push(boxKey(type,level));burst(m.x,m.y-15,'#edd58c',12);save();return type}
function grantRoundLoot(won){const rewards={money:0,boxes:[],drops:[...(run.droppedBoxes||[])]};if(!won||run.trial||run.tutorial)return rewards;rewards.money=500*run.id;player.loot.money=Math.min(999999999,player.loot.money+rewards.money);const rank=calculateResult(run).rank,count={S:1,SS:2,SSS:3}[rank]||0;for(let i=0;i<count;i++){const type=randomBoxType();const level=boxTierForLevel(stageById(run.id)?.level||0);if(level&&addBox(type,level))rewards.boxes.push(boxKey(type,level))}return rewards}
const POTION_PRICES={hpPotion:{buy:100,sell:50},mpPotion:{buy:100,sell:50}};
function tradePotion(id,buy,quantity=1){if(player.map!=='town'||!POTION_PRICES[id]||!Number.isInteger(quantity)||quantity<1||quantity>9999)return false;const price=POTION_PRICES[id],stock=player.consumables[id];if(buy){if(player.loot.money<price.buy*quantity||stock+quantity>999999)return false;player.loot.money-=price.buy*quantity;player.consumables[id]+=quantity}else{if(stock<quantity||player.loot.money+price.sell*quantity>99999999999)return false;player.consumables[id]-=quantity;player.loot.money+=price.sell*quantity}save();updateUI();return true}
let tradeOverlay=null;
function closeTradePopup(){if(tradeOverlay){tradeOverlay.remove();tradeOverlay=null}}
function salePrice(item){return item.kind==='potion'?50:item.kind==='box'?100:{common:100,rare:250,epic:750,legend:2000}[item.gear.rarity]}
function sellOwnedItem(item,quantity){if(player.map!=='town'||!Number.isInteger(quantity)||quantity<1)return false;if(item.kind==='potion')return tradePotion(item.id,false,quantity);if(item.kind==='box'){if(!consumeBoxes(item.id,quantity))return false}else{if(quantity!==1||Object.values(player.loot.equipped).includes(item.id))return false;const index=player.loot.gear.findIndex(g=>g.id===item.id);if(index<0)return false;player.loot.gear.splice(index,1)}player.loot.money=Math.min(999999999,player.loot.money+salePrice(item)*quantity);save();updateUI();return true}
function showTradePopup(item,buy){closeTradePopup();hideUpgradeTooltip();const overlay=document.createElement('div');overlay.className='trade-overlay';tradeOverlay=overlay;const card=document.createElement('section');card.className='dialog-card trade-card';card.setAttribute('role','dialog');card.setAttribute('aria-modal','true');const title=document.createElement('h2');title.textContent=(buy?'ซื้อ ':'ขาย ')+item.name;const close=document.createElement('button');close.className='window-close';close.textContent='×';close.setAttribute('aria-label','ปิดจำนวนซื้อขาย');close.onclick=closeTradePopup;const price=buy?(item.kind==='skillbox'?1000:100):salePrice(item);const label=document.createElement('label');label.textContent='จำนวน';const input=document.createElement('input');input.type='number';input.min=1;input.step=1;input.value=1;input.setAttribute('aria-label','จำนวนซื้อขาย');label.append(input);const increments=document.createElement('div');increments.className='trade-increments';for(const n of [1,10,'MAX']){const button=document.createElement('button');button.textContent=n==='MAX'?'MAX':'+'+n;button.onclick=()=>{input.value=n==='MAX'?available():Math.min(available(),Math.max(0,Number(input.value)||0)+n);refresh()};increments.append(button)}const total=document.createElement('p');const confirm=document.createElement('button');confirm.className='primary';confirm.textContent=buy?'ยืนยันซื้อ':'เลือกสำหรับขาย';const available=()=>buy?Math.min(item.kind==='skillbox'?999999-player.loot.boxes.secondary:9999-player.consumables[item.id],Math.floor(player.loot.money/price)):item.kind==='potion'?player.consumables[item.id]:item.kind==='box'?boxCount(item.id):1;const refresh=()=>{const n=Number(input.value);total.textContent='ราคา '+price.toLocaleString()+' / ชิ้น · รวม '+(Number.isFinite(n)?Math.max(0,n)*price:0).toLocaleString()+' เหรียญเงิน';input.max=available();confirm.disabled=!Number.isInteger(n)||n<1||n>available();};input.oninput=refresh;confirm.onclick=()=>{const n=Number(input.value);if(confirm.disabled)return;const success=buy?(item.kind==='skillbox'?buySkillBoxes(n):tradePotion(item.id,true,n)):(saleSelections.set(item.kind+':'+item.id,{item,quantity:n}),true);if(success){closeTradePopup();openPotionShop()}};const detail=document.createElement('p');detail.className='sale-item-detail';detail.textContent=buy?'':item.kind==='gear'?gearDescription(item.gear):item.kind==='potion'?item.potion.description:boxDescription(item.id);card.append(close,title,detail,label,increments,total,confirm);overlay.append(card);document.body.append(overlay);refresh();input.focus();input.select()}
let shopInventoryCategory="usable";
function openPotionShop(){if(player.map!=='town'||screen!=='play')return;const body=document.createElement('div');body.className='potion-shop';const stock=document.createElement('section');stock.className='shop-stock';const heading=document.createElement('h3');heading.textContent='ของร้านค้า';stock.append(heading);for(const [id,item]of Object.entries(POTION_ITEMS)){const cell=document.createElement('button');cell.className='shop-product '+item.kind+'-potion';cell.setAttribute('aria-label','ซื้อ '+item.name);const icon=document.createElement('span');icon.className='potion-bottle';const name=document.createElement('strong');name.textContent=item.name;const desc=document.createElement('p');desc.textContent='ฟื้นฟู '+item.kind.toUpperCase()+' 35% ของค่าสูงสุด · คูลดาวน์ 2 วินาที';const price=document.createElement('small');price.textContent='100 เหรียญเงิน / ขวด';cell.append(icon,name,desc,price);cell.onclick=()=>showTradePopup({kind:'potion',id,name:item.name},true);stock.append(cell)}const product=document.createElement('button');product.className='shop-product';product.setAttribute('aria-label','ซื้อ กล่องสุ่มสกิล ขั้น 1');product.innerHTML=boxIcon('secondary');const title=document.createElement('strong');title.textContent='กล่องสุ่มสกิล ขั้น 1';const price=document.createElement('small');price.textContent='1,000 เหรียญเงิน / กล่อง';product.append(title,price);product.onclick=()=>showTradePopup({kind:'skillbox',id:'secondary',name:'กล่องสุ่มสกิล ขั้น 1'},true);stock.append(product);body.append(stock);const bag=document.createElement('section');bag.className='shop-bag';const bagTitle=document.createElement('h3');bagTitle.textContent='ของตัวละคร';bag.append(bagTitle);const tabs=document.createElement('div');tabs.className='inventory-tabs shop-tabs';for(const [id,label]of [['equipment','สวมใส่'],['usable','ใช้งาน'],['locked3','หมวด 3'],['locked4','หมวด 4']]){const tab=document.createElement('button');tab.textContent=label;tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(id===shopInventoryCategory));tab.classList.toggle('selected',id===shopInventoryCategory);tab.disabled=id.startsWith('locked');tab.onclick=()=>{shopInventoryCategory=id;openPotionShop()};tabs.append(tab)}tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','หมวดไอเทมร้านค้า');bag.append(tabs);const grid=document.createElement('div');grid.className='shop-sale-grid';const items=[...Object.entries(POTION_ITEMS).filter(([id])=>player.consumables[id]>0).map(([id,p])=>({kind:'potion',id,name:p.name,count:player.consumables[id],potion:p})),...boxStacks().map(item=>({...item,kind:'box'})),...bagEquipment().map(g=>({kind:'gear',id:g.id,name:g.name,count:1,gear:g}))];const filtered=items.filter(item=>shopInventoryCategory==='equipment'?item.kind==='gear':item.kind!=='gear');for(let i=0;i<Math.max(20,filtered.length);i++){const item=filtered[i],cell=document.createElement(item?'button':'div');cell.className='inventory-cell';if(item){cell.classList.add('inventory-item');cell.setAttribute('aria-label','ขาย '+item.name);if(item.kind==='potion'){cell.classList.add(item.potion.kind+'-potion');const bottle=document.createElement('span');bottle.className='potion-bottle';cell.append(bottle)}else if(item.kind==='box'){cell.innerHTML=boxIcon(item.id);appendBoxLevel(cell,item.id);cell.classList.add('loot-box')}else{cell.innerHTML=gearIcon(item.gear);cell.style.color=LOOT_RARITIES[item.gear.rarity].color;cell.style.borderColor=LOOT_RARITIES[item.gear.rarity].color}const amount=document.createElement('strong');amount.className='item-count';amount.textContent=item.count;cell.append(amount);const equipped=item.kind==='gear'&&Object.values(player.loot.equipped).includes(item.id);attachLootDetail(cell,{name:item.name,description:(item.kind==='gear'?gearDescription(item.gear):item.kind==='potion'?item.potion.description:boxDescription(item.id))+'\nขาย '+salePrice(item)+' เหรียญเงิน / ชิ้น'+(equipped?'\nกำลังสวมใส่ · ขายไม่ได้':'')});cell.disabled=equipped;cell.classList.toggle('sale-selected',saleSelections.has(item.kind+':'+item.id));cell.setAttribute('aria-pressed',String(saleSelections.has(item.kind+':'+item.id)));cell.onclick=()=>{const key=item.kind+':'+item.id;if(saleSelections.has(key)){saleSelections.delete(key);openPotionShop()}else if(item.kind==='gear'){saleSelections.set(key,{item,quantity:1});openPotionShop()}else showTradePopup(item,false)}}grid.append(cell)}bag.append(grid);const sell=document.createElement('button');sell.id='batchSellBtn';sell.className='primary';sell.textContent='ขาย ('+saleSelections.size+' รายการ)';sell.disabled=!saleSelections.size;sell.onclick=showSaleReview;bag.append(sell);body.append(bag);modal('มิล่า · ร้านยา',body,[]);$('modal').classList.add('shop-modal')}
function drawPotionMerchant(){const x=335,y=290;ctx.save();ctx.translate(x,y);ellipse(0,-1,13,3,'#27473855');rect(-8,-17,7,17,'#594c49');rect(2,-17,7,17,'#594c49');rect(-11,-34,22,22,'#a68dc3');rect(-7,-29,14,17,'#f4e5c0');rect(-14,-29,5,14,'#e3b58e');rect(10,-29,5,14,'#e3b58e');rect(-9,-47,18,17,'#edc69e');rect(-12,-50,24,7,'#584134');rect(-12,-45,6,18,'#584134');rect(7,-45,5,18,'#584134');rect(-15,-51,30,5,'#8d6eab');rect(-8,-58,17,8,'#aa89c5');rect(8,-24,8,12,'#78b9d5');rect(10,-28,4,4,'#dcc698');ctx.font='11px Thai,Tahoma';ctx.textAlign='center';ctx.fillStyle='#183127';ctx.fillRect(-43,-84,86,22);ctx.fillStyle='#f2dfb4';ctx.fillText('มิล่า · ร้านยา',0,-69);ctx.font='9px Thai,Tahoma';ctx.fillText('Spacebar',0,14);ctx.restore()}
const EQUIPMENT_CAPACITY=100;
function openLootBoxes(type,quantity=1){if(boxType(type)==='secondary'&&skillBoxTier(type)!==1){toast('ขั้นนี้ยังรอออกแบบ · เก็บกล่องไว้ก่อน');return []}if(!BOX_TYPES[boxType(type)]||!Number.isInteger(quantity)||quantity<1)return [];if(boxType(type)!=='secondary'&&bagEquipment().length+quantity>EQUIPMENT_CAPACITY){toast('กระเป๋าอุปกรณ์เต็มหรือพื้นที่ไม่พอ กรุณาขายไอเทมก่อนเปิดกล่อง');return []}if(boxCount(type)<quantity){toast('จำนวนกล่องไม่พอ');return []}const level=boxLevel(type),baseType=boxType(type);if(baseType==='secondary'){const skills=Array.from({length:quantity},()=>({skillId:rollSkillScroll(skillBoxTier(type))}));consumeBoxes(type,quantity);for(const item of skills)player.skillScrolls[item.skillId]=(player.skillScrolls[item.skillId]||0)+1;save();return skills}const items=Array.from({length:quantity},()=>generateGear(baseType,Math.min(4,Math.floor(level/10)),level));consumeBoxes(type,quantity);player.loot.gear.push(...items);save();return items}
function openLootBox(type){return openLootBoxes(type,1)[0]||null}
function finishBoxOpening(type,quantity){const items=openLootBoxes(type,quantity);if(!items.length)return false;closeTradePopup();renderCharacterWindow();updateUI();toast(items[0].skillId?'ได้รับสกิล '+items.length+' ชิ้น · ดูหมวดสกิล':items.length===1?'ได้รับ '+LOOT_RARITIES[items[0].rarity].name+' · '+items[0].name:'เปิดกล่องแล้ว '+items.length+' กล่อง · ดูอุปกรณ์ในหมวดสวมใส่');return true}
function bindBoxOpening(button,type){let pending=null;button.onclick=e=>{if(pending)clearTimeout(pending);if(e.detail>=2)return;pending=setTimeout(()=>{pending=null;if(button.isConnected&&!$('characterOverlay').hidden)showBoxDialog(type)},400)};button.ondblclick=e=>{e.preventDefault();if(pending)clearTimeout(pending);pending=null;closeTradePopup();finishBoxOpening(type,1)}}
function showBoxDialog(type){if(boxType(type)==='secondary'&&skillBoxTier(type)!==1){toast('ขั้นนี้ยังรอออกแบบ · เก็บกล่องไว้ก่อน');return}if(boxType(type)!=='secondary'&&bagEquipment().length>=EQUIPMENT_CAPACITY){toast('กระเป๋าอุปกรณ์เต็ม กรุณาขายไอเทมก่อนเปิดกล่อง');return}closeTradePopup();hideUpgradeTooltip();const overlay=document.createElement('div');overlay.className='trade-overlay';tradeOverlay=overlay;const card=document.createElement('section');card.className='dialog-card trade-card';card.setAttribute('role','dialog');card.setAttribute('aria-modal','true');const heading=document.createElement('h2');heading.textContent='เปิด '+boxName(type);const close=document.createElement('button');close.className='window-close';close.textContent='×';close.setAttribute('aria-label','ปิดจำนวนเปิดกล่อง');close.onclick=closeTradePopup;const label=document.createElement('label');label.textContent='จำนวน';const input=document.createElement('input');input.type='number';input.min=1;input.step=1;input.value=1;input.setAttribute('aria-label','จำนวนเปิดกล่อง');label.append(input);const increments=document.createElement('div');increments.className='trade-increments';const limit=()=>Math.max(0,Math.min(boxCount(type),boxType(type)==='secondary'?999999:EQUIPMENT_CAPACITY-bagEquipment().length));for(const n of [1,10,'MAX']){const button=document.createElement('button');button.textContent=n==='MAX'?'MAX':'+'+n;button.onclick=()=>{input.value=n==='MAX'?limit():Math.min(limit(),Math.max(0,Number(input.value)||0)+n);refresh()};increments.append(button)}const info=document.createElement('p');const confirm=document.createElement('button');confirm.className='primary';confirm.textContent='เปิดกล่อง';const refresh=()=>{const n=Number(input.value),free=Math.max(0,EQUIPMENT_CAPACITY-bagEquipment().length);input.max=limit();info.textContent=boxDescription(type)+'\nมีกล่อง '+boxCount(type)+' · ช่องอุปกรณ์ว่าง '+free+' / '+EQUIPMENT_CAPACITY+(n>free&&boxType(type)!=='secondary'?'\nพื้นที่ไม่พอ กรุณาขายไอเทมก่อนเปิดกล่อง':'');confirm.disabled=!Number.isInteger(n)||n<1||n>limit()};input.oninput=refresh;confirm.onclick=()=>{if(!confirm.disabled)finishBoxOpening(type,Number(input.value))};card.append(close,heading,label,increments,info,confirm);overlay.append(card);document.body.append(overlay);refresh();input.focus();input.select()}
function showGearDialog(g){if(g.weapon){modal(g.name,gearDescription(g),[['สวมมือหลัก',()=>equipWeaponHand(g,'main'),true],['สวมมือรอง · ATK 50%',()=>equipWeaponHand(g,'secondary')]]);return}modal(g.name,gearDescription(g),[['ปิด',closeModal],['สวมใส่',()=>{equipOwnedGear(g);player.hp=Math.min(player.hp,maxHP());player.mp=Math.min(player.mp,maxMP());save();renderCharacterWindow();updateUI();closeModal()},true]])}
function gearIcon(g){if(g.weapon)return weaponIcon(g.weapon);const paths={hat:'<path d="M3 15h18v4H3zM6 15V7l6-4 6 4v8" fill="currentColor"/>',shirt:'<path d="m8 4-6 5 3 4 3-2v10h8V11l3 2 3-4-6-5-4 3Z" fill="currentColor"/>',gloves:'<path d="M6 20V8h3v5V4h3v9V6h3v9l3-3 2 3-6 7Z" fill="currentColor"/>',shoes:'<path d="M5 3h7v11l8 3v5H3v-6h2Z" fill="currentColor"/>',accessory1:'<circle cx="12" cy="14" r="7" fill="none" stroke="currentColor" stroke-width="3"/><path d="m8 5 4-3 4 3-4 4Z" fill="currentColor"/>',accessory2:'<path d="M4 3q0 14 8 15Q20 17 20 3" fill="none" stroke="currentColor" stroke-width="2"/><path d="m8 18 4-4 4 4-4 5Z" fill="currentColor"/>'};return g.slot==='main'?itemIcon('sword'):g.slot==='secondary'?itemIcon('shield'):'<svg viewBox="0 0 24 24" aria-hidden="true">'+paths[g.slot]+'</svg>'}
function attachLootDetail(cell,item){cell.onmouseenter=()=>showItemDetail(cell,item);cell.onmouseleave=()=>hideUpgradeTooltip(false);cell.onfocus=()=>showItemDetail(cell,item)}

function bagEquipment(p=player){const equipped=new Set(Object.values(p.loot?.equipped||{}));return (p.loot?.gear||[]).filter(g=>!equipped.has(g.id))}
function equipOwnedGear(g){if(!player.loot.gear.some(owned=>owned.id===g.id))return false;const old=equippedItems().find(i=>i.slot===g.slot);if(old?.item&&!old.id&&!player.starterStored){player.starterStored=true;player.loot.gear.push({id:crypto.randomUUID(),name:old.item,weapon:old.weapon,slot:old.slot,rarity:'common',stage:0,atk:old.atk||0,def:old.def||0,hp:old.hp||0,mp:old.mp||0,bonuses:[]})}player.loot.equipped[g.slot]=g.id;return true}
const saleSelections=new Map();
function showSaleReview(){closeTradePopup();hideUpgradeTooltip();const entries=[...saleSelections.values()];if(!entries.length)return;const overlay=document.createElement('div');overlay.className='trade-overlay';tradeOverlay=overlay;const card=document.createElement('section');card.className='dialog-card sale-review';card.setAttribute('role','dialog');card.setAttribute('aria-modal','true');const title=document.createElement('h2');title.textContent='ยืนยันรายการขาย';const close=document.createElement('button');close.className='window-close';close.textContent='×';close.setAttribute('aria-label','ปิดรายการขาย');close.onclick=closeTradePopup;const list=document.createElement('div');list.className='sale-review-list';let total=0;for(const {item,quantity}of entries){const row=document.createElement('section');const name=document.createElement('strong');name.textContent=item.name+' × '+quantity;const detail=document.createElement('p');detail.textContent=item.kind==='gear'?gearDescription(item.gear):item.kind==='potion'?item.potion.description:boxDescription(item.id);const price=document.createElement('b');price.textContent='ขาย '+salePrice(item)+' / ชิ้น · รวม '+(salePrice(item)*quantity).toLocaleString()+' เหรียญเงิน';row.append(name,detail,price);list.append(row);total+=salePrice(item)*quantity}const sum=document.createElement('p');sum.textContent='รวม '+total.toLocaleString()+' เหรียญเงิน';const confirm=document.createElement('button');confirm.className='primary';confirm.textContent='ยืนยันขาย';confirm.onclick=()=>{if(commitSelectedSale()){closeTradePopup();openPotionShop()}else toast('รายการไอเทมเปลี่ยนแล้ว กรุณาเลือกใหม่')};card.append(close,title,list,sum,confirm);overlay.append(card);document.body.append(overlay)}
function commitSelectedSale(){if(player.map!=='town'||!saleSelections.size)return false;const entries=[...saleSelections.values()];let total=0;for(const {item,quantity}of entries){if(!Number.isInteger(quantity)||quantity<1)return false;if(item.kind==='gear'){if(quantity!==1||!bagEquipment().some(g=>g.id===item.id))return false}else if(item.kind==='potion'){if(!POTION_ITEMS[item.id]||player.consumables[item.id]<quantity)return false}else if(item.kind==='box'){if(!BOX_TYPES[boxType(item.id)]||boxCount(item.id)<quantity)return false}else return false;total+=salePrice(item)*quantity}if(player.loot.money+total>999999999)return false;for(const {item,quantity}of entries){if(item.kind==='gear')player.loot.gear=player.loot.gear.filter(g=>g.id!==item.id);else if(item.kind==='potion')player.consumables[item.id]-=quantity;else consumeBoxes(item.id,quantity)}player.loot.money+=total;saleSelections.clear();save();updateUI();return true}

function boxIcon(type){type=boxType(type);const symbol=type==='main'?itemIcon('sword'):type==='secondary'?'<svg viewBox="0 0 24 24"><path d="M5 3h14v18H5Z" fill="#d7c08c"/><path d="M9 7h6M9 11h6M9 15h4" stroke="#395347"/></svg>':gearIcon({slot:type==='armor'?'shirt':'accessory1'});return '<span class="box-type-icon"><svg class="box-outline" viewBox="0 0 48 48" aria-hidden="true"><path d="M5 14h38v28H5zM3 10h42v9H3z" fill="#79633e" stroke="#e4cb8e" stroke-width="2"/></svg><span class="box-symbol">'+symbol+'</span></span>'}

function appendBoxLevel(cell,id){const label=document.createElement("small");label.className="box-level";label.textContent=boxType(id)==='secondary'?'ขั้น '+skillBoxTier(id):"Lv."+boxLevel(id);cell.append(label)}

function equipWeaponHand(g,hand){g=player.loot.gear.find(item=>item.id===g.id);if(!g||!['main','secondary'].includes(hand)||!validClass().weapons.includes(g.weapon)){toast('อาชีพนี้ใช้อาวุธนี้ไม่ได้');return false}const oldHand=Object.keys(player.loot.equipped).find(k=>player.loot.equipped[k]===g.id);if(oldHand){if(oldHand!==hand){const displaced=player.loot.gear.find(item=>item.id===player.loot.equipped[hand]);if(displaced){displaced.slot=oldHand;player.loot.equipped[oldHand]=displaced.id}else delete player.loot.equipped[oldHand];g.slot=hand;player.loot.equipped[hand]=g.id}}else{g.slot=hand;equipOwnedGear(g)}save();closeModal();renderCharacterWindow();updateUI();return true}
function buySkillBoxes(quantity){if(player.map!=='town'||!Number.isInteger(quantity)||quantity<1||quantity>999999-player.loot.boxes.secondary||player.loot.money<quantity*1000)return false;player.loot.money-=quantity*1000;for(let i=0;i<quantity;i++)addBox('secondary',10);save();updateUI();return true}
